      ]
    },
    {
      "service": "worker",
      "kind": "runtime_fault",
      "mechanism": "Worker process is stuck due to payment-service failures, causing invoice file write errors and dead letters",
      "supporting": ["E14", "E16", "E2", "E4", "E7", "E9", "E32"],
      "refuting": [],
      "explains": ["M2_error_burst", "M3_dead_letters"],
      "repair_plan": [
        {"action": "restart_service", "params": {"service": "worker"}}
      ]
    },
    {
      "service": "sync-job",
      "kind": "runtime_fault",
      "mechanism": "Sync-job process is stuck independently, causing ledger export write failures",
      "supporting": ["E15", "E3", "E6", "E32"],
      "refuting": [],
      "explains": ["E3", "E6"],
      "repair_plan": [
        {"action": "restart_service", "params": {"service": "sync-job"}}
      ]
    }
  ],
  "summary": "Payment-service disk exhaustion is the primary cause, with worker and sync-job also experiencing runtime faults."
}
